"""Independent reference implementation using fractions.Fraction."""
from fractions import Fraction as Fr


def decode(ebits, fbits, h):
    eall = (1 << ebits) - 1
    F = 1 << fbits
    w = 1 + ebits + fbits
    v = int(h, 16) & ((1 << w) - 1)
    s = (v >> (ebits + fbits)) & 1
    e = (v >> fbits) & eall
    f = v & (F - 1)
    bias = (1 << (ebits - 1)) - 1
    if e == eall:
        if f == 0:
            return ('inf', s)
        return ('nan', s, f)
    if e == 0:
        val = Fr(f) * Fr(1 << (1 - bias - fbits))
    else:
        val = Fr(F + f) * Fr(1 << (e - bias - fbits))
    return ('num', s, val)


def floor_log2(x):  # x > 0 Fraction
    lo = -4000
    hi = 4000
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if Fr(1 << 4000) if False else None:
            pass
        if x >= Fr(2) ** mid:
            lo = mid
        else:
            hi = mid - 1
    return lo


def ref(req):
    ebits, fbits, mode, pairs = req['ebits'], req['fbits'], req['mode'], req['pairs']
    eall = (1 << ebits) - 1
    bias = (1 << (ebits - 1)) - 1
    F = 1 << fbits
    emin = 1 - bias
    emax = eall - 1 - bias
    w = 1 + ebits + fbits

    nan = False
    invalid = False
    infs = []      # signs of infinite products
    terms = []     # (sign, Fraction value) for finite products
    for a, b in pairs:
        A = decode(ebits, fbits, a)
        B = decode(ebits, fbits, b)
        if A[0] == 'nan' or B[0] == 'nan':
            nan = True
            for X in (A, B):
                if X[0] == 'nan' and not (X[2] >> (fbits - 1)) & 1:
                    invalid = True
            continue
        if A[0] == 'inf' or B[0] == 'inf':
            zero = lambda X: X[0] == 'num' and X[2] == 0
            if (A[0] == 'inf' and zero(B)) or (B[0] == 'inf' and zero(A)):
                invalid = True
                continue
            infs.append(A[1] ^ B[1])
            continue
        va = (-1) ** A[1] * A[2]
        vb = (-1) ** B[1] * B[2]
        terms.append((A[1] ^ B[1], va * vb))

    if nan or invalid:
        bits = (eall << fbits) | (1 << (fbits - 1))
        return {'bits': format(bits, 'x'), 'flags': ['invalid'] if invalid else []}
    if infs:
        if 0 in infs and 1 in infs:
            bits = (eall << fbits) | (1 << (fbits - 1))
            return {'bits': format(bits, 'x'), 'flags': ['invalid']}
        s = infs[0]
        bits = (s << (ebits + fbits)) | (eall << fbits)
        return {'bits': format(bits, 'x'), 'flags': []}

    total = sum(((-1) ** s) * v for s, v in terms) if terms else Fr(0)
    if total == 0:
        negz = (mode == 'RDN') or (len(terms) > 0 and all(s == 1 and v == 0 for s, v in terms))
        return {'bits': format(negz << (ebits + fbits), 'x'), 'flags': []}

    sign = 1 if total < 0 else 0
    x = abs(total)
    L = floor_log2(x)
    Q = max(emin - fbits, L - fbits)
    q = Fr(2) ** Q
    r = x / q
    fl = r.numerator // r.denominator
    frac = r - fl
    if frac == 0:
        n = fl
    else:
        half = Fr(1, 2)
        if frac > half:
            up = True
        elif frac < half:
            up = False
        else:
            if mode == 'RNE':
                up = (fl & 1) == 1
            elif mode == 'RNA':
                up = True
            elif mode == 'RTZ':
                up = False
            elif mode == 'RUP':
                up = (sign == 0)
            else:
                up = (sign == 1)
        n = fl + 1 if up else fl
    y = n * q
    inexact = (y != x)
    if y >= Fr(2) ** (emax + 1):
        away = (mode in ('RNE', 'RNA') or (mode == 'RUP' and sign == 0)
                or (mode == 'RDN' and sign == 1))
        if away:
            bits = (sign << (ebits + fbits)) | (eall << fbits)
        else:
            bits = (sign << (ebits + fbits)) | ((eall - 1) << fbits) | (F - 1)
        return {'bits': format(bits, 'x'), 'flags': ['overflow', 'inexact']}
    flags = []
    if inexact:
        flags.append('inexact')
        if y < Fr(2) ** emin:
            flags.append('underflow')
    # encode
    if y == 0:
        e_field, frac = 0, 0
    elif y < Fr(2) ** emin:
        e_field = 0
        frac = int(y / Fr(2) ** (emin - fbits))
    else:
        Ly = floor_log2(y)
        e_field = Ly + bias
        frac = int(y / Fr(2) ** (Ly - fbits)) - F
    bits = (sign << (ebits + fbits)) | (e_field << fbits) | frac
    return {'bits': format(bits, 'x'), 'flags': flags}
